INSERT INTO `v1_5693ebd193831154c3cffc23c56fbab7770f4dee1962d83583975cf9d49f5810` VALUES (13161, "やってやるですよ！", 0, "61_inori_guts", 106601, "50％でアルファルピ×2000\nさらに次のイベントへ", 0, 13161);
INSERT INTO `v1_5693ebd193831154c3cffc23c56fbab7770f4dee1962d83583975cf9d49f5810` VALUES (23141, "もう一回挑戦だ！", 0, "52_ruka_fishing", 105601, "25％で★2迷宮遺物×1\nさらに次のイベントへ", 0, 23141);
INSERT INTO `v1_5693ebd193831154c3cffc23c56fbab7770f4dee1962d83583975cf9d49f5810` VALUES (23151, "まだまだ\n食べ足りません☆", 1, "92_peko_guts", 105801, "50％で次のイベントへ", 0, 23151);
INSERT INTO `v1_5693ebd193831154c3cffc23c56fbab7770f4dee1962d83583975cf9d49f5810` VALUES (23152, "それくらいで\nいいんじゃない？", 0, "92_kyaru_sad", 106001, "ランダムなロールの\nランダムサイン×2", 0, 23152);
INSERT INTO `v1_5693ebd193831154c3cffc23c56fbab7770f4dee1962d83583975cf9d49f5810` VALUES (23161, "今日はツイてるです！", 1, "62_inori_guts", 106601, "50％でアルファルピ×4000\nさらに次のイベントへ", 2000, 23161);
INSERT INTO `v1_5693ebd193831154c3cffc23c56fbab7770f4dee1962d83583975cf9d49f5810` VALUES (23162, "もうこの辺で……", 0, "62_ayumi_sad", 105501, "挑戦終了", 0, 23162);
INSERT INTO `v1_5693ebd193831154c3cffc23c56fbab7770f4dee1962d83583975cf9d49f5810` VALUES (33141, "最後にもうひと勝負！", 0, "53_ruka_fishing", 105601, "10％で★3迷宮遺物×1", 0, 33141);
INSERT INTO `v1_5693ebd193831154c3cffc23c56fbab7770f4dee1962d83583975cf9d49f5810` VALUES (33151, "えへへ～\nもうちょっとだけ……", 1, "93_peko_guts", 105801, "50％でオールセレクトサイン×２", 0, 33151);
INSERT INTO `v1_5693ebd193831154c3cffc23c56fbab7770f4dee1962d83583975cf9d49f5810` VALUES (33152, "そんなに\n食べきれないでしょ！", 0, "93_kyaru_anger", 106001, "ランダムなロールの\nセレクトサイン×2", 0, 33152);
INSERT INTO `v1_5693ebd193831154c3cffc23c56fbab7770f4dee1962d83583975cf9d49f5810` VALUES (33161, "今日のあたしは\n負け知らずです！", 1, "63_inori_guts", 106601, "50％でアルファルピ×8000", 4000, 33161);
INSERT INTO `v1_5693ebd193831154c3cffc23c56fbab7770f4dee1962d83583975cf9d49f5810` VALUES (33162, "そろそろやめた方が……", 0, "63_ayumi_worry", 105501, "挑戦終了", 0, 33162);
